#!/usr/bin/env bash
# Devcontainer post-create bootstrap for Gameplane (generated profiles).
#
# Usage: bash .devcontainer/setup.sh <path to setup.env>
#
# setup.env is generated by hack/gen-devcontainers.py for each profile. It
# lists the steps this container needs (STEPS, in run order), the steps that
# may fail without failing the setup (OPTIONAL_STEPS), the pinned versions
# (<TOOL>_VERSION, from .devcontainer/versions.toml), and the Go modules,
# submodules and ready message for the profile.
#
# Installs the extra tooling the Makefile expects but the devcontainer
# features don't provide (kind, oras, golangci-lint, envtest, uv, specify),
# pre-fetches Go modules + envtest assets, and installs the web/website npm
# deps so the first `make test` / `make web-dev` run is fast.
#
# Idempotent: every step is `command -v` or version guarded.
#
# Credentials: this script never reads or writes credentials. The AI coding
# CLIs are installed but not logged in; each authenticates interactively at
# runtime (its login flow or API-key env var), keeping the image shareable
# and secret-free.

set -euo pipefail

log() { printf "\n\033[1;34m[devcontainer]\033[0m %s\n" "$*"; }
die() { printf "\n\033[1;31m[devcontainer] ERROR:\033[0m %s\n" "$*" >&2; exit 1; }

if [ "$#" -ne 1 ]; then
	echo "usage: setup.sh <setup.env>" >&2
	exit 2
fi

# Resolve the env file against the caller's cwd before moving to the repo root.
ENV_FILE_ARG="$1"
[ -f "$ENV_FILE_ARG" ] || die "setup.env not found: $ENV_FILE_ARG"
ENV_FILE="$(cd "$(dirname "$ENV_FILE_ARG")" && pwd)/$(basename "$ENV_FILE_ARG")"

# This script lives in <root>/.devcontainer/ (or <submodule>/.devcontainer/).
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

# shellcheck source=/dev/null
. "$ENV_FILE"

: "${STEPS:=}"
: "${OPTIONAL_STEPS:=}"
: "${GO_MODULES:=}"
: "${SUBMODULES:=}"
: "${WEBSITE_DIR:=website}"
: "${MODULES_DIR:=modules}"
: "${READY:=}"

# PATH: go-installed binaries and uv/specify live in these directories.
if command -v go >/dev/null 2>&1; then
	GOBIN_DIR="$(go env GOPATH)/bin"
	mkdir -p "$GOBIN_DIR"
	case ":$PATH:" in *":$GOBIN_DIR:"*) ;; *) export PATH="$GOBIN_DIR:$PATH" ;; esac
fi
LOCAL_BIN_DIR="$HOME/.local/bin"
mkdir -p "$LOCAL_BIN_DIR"
case ":$PATH:" in *":$LOCAL_BIN_DIR:"*) ;; *) export PATH="$LOCAL_BIN_DIR:$PATH" ;; esac

is_optional() {
	local s
	for s in $OPTIONAL_STEPS; do
		[ "$s" = "$1" ] && return 0
	done
	return 1
}

# ---------- submodules (modules/ lives in the GameplanePanel/module repo) ----------
# The game-module bundles are a git submodule at modules/; init them so
# `make modules-push` / `make dev-up` find modules/build.sh and the bundles.
step_submodules() {
	if [ -f .gitmodules ] && [ -n "$SUBMODULES" ]; then
		log "git submodule update --init --recursive ($SUBMODULES)"
		# SUBMODULES is a space-separated path list; word splitting is intended.
		git submodule update --init --recursive -- $SUBMODULES
	fi
}

# ---------- python3 ----------
# The base image has no python3, but hack/*.py (make devcontainers, check-*
# scripts) and modules/validate.py run on it.
step_python3() {
	if ! command -v python3 >/dev/null 2>&1; then
		log "installing python3"
		sudo apt-get update
		sudo apt-get install -y --no-install-recommends python3
	fi
}

# ---------- PyYAML (modules/validate.py imports yaml) ----------
step_pyyaml() {
	if ! python3 -c 'import yaml' 2>/dev/null; then
		log "installing python3-yaml"
		sudo apt-get update
		sudo apt-get install -y --no-install-recommends python3-yaml
	fi
}

# ---------- kind ----------
step_kind() {
	if command -v kind >/dev/null 2>&1 \
		&& kind version 2>/dev/null | grep -qF "kind ${KIND_VERSION} "; then
		return 0
	fi
	local arch tmp
	arch="$(dpkg --print-architecture)"   # amd64 | arm64
	log "installing kind ${KIND_VERSION}"
	tmp="$(mktemp)"
	curl -fsSL -o "$tmp" \
		"https://kind.sigs.k8s.io/dl/${KIND_VERSION}/kind-linux-${arch}"
	sudo install -m 0755 "$tmp" /usr/local/bin/kind
	rm -f "$tmp"
}

# ---------- oras (≥ 1.2.0; required by modules/build.sh) ----------
step_oras() {
	if command -v oras >/dev/null 2>&1 \
		&& oras version 2>/dev/null | grep -qF "${ORAS_VERSION}"; then
		return 0
	fi
	local arch tmp
	arch="$(dpkg --print-architecture)"   # amd64 | arm64
	log "installing oras ${ORAS_VERSION}"
	tmp="$(mktemp -d)"
	curl -fsSL -o "$tmp/oras.tar.gz" \
		"https://github.com/oras-project/oras/releases/download/v${ORAS_VERSION}/oras_${ORAS_VERSION}_linux_${arch}.tar.gz"
	sudo tar -C /usr/local/bin -xzf "$tmp/oras.tar.gz" oras
	sudo chmod 0755 /usr/local/bin/oras
	rm -rf "$tmp"
}

# ---------- golangci-lint ----------
# v2 release binaries work with the in-container Go version. The
# .golangci.yml has been migrated from v1 to v2 schema (v2 introduces new
# linters and removes deprecated ones).
step_golangci_lint() {
	local bin_dir bin
	bin_dir="$(go env GOPATH)/bin"
	bin="$bin_dir/golangci-lint"
	if "$bin" --version 2>/dev/null | grep -qF "${GOLANGCI_LINT_VERSION#v}"; then
		return 0
	fi
	log "installing golangci-lint ${GOLANGCI_LINT_VERSION}"
	GOBIN="$bin_dir" go install \
		"github.com/golangci/golangci-lint/v2/cmd/golangci-lint@${GOLANGCI_LINT_VERSION}"
}

# ---------- envtest assets (K8s ${ENVTEST_K8S_VERSION}; pulled lazily by the Makefile but
# we warm the cache here so the first `make test-integration` doesn't
# need network) ----------
step_envtest() {
	local bin_dir bin
	bin_dir="$(go env GOPATH)/bin"
	bin="$bin_dir/setup-envtest"
	if [ ! -x "$bin" ]; then
		log "installing setup-envtest ${SETUP_ENVTEST_VERSION}"
		GOBIN="$bin_dir" go install \
			"sigs.k8s.io/controller-runtime/tools/setup-envtest@${SETUP_ENVTEST_VERSION}"
	fi
	log "fetching envtest binaries for K8s ${ENVTEST_K8S_VERSION}"
	"$bin" use "${ENVTEST_K8S_VERSION}" >/dev/null
}

# ---------- Go module cache warmup ----------
# GO_MODULES is generated from go.work 'use' entries (in go.work order) for
# the modules this profile covers.
step_go_mod_download() {
	local m
	for m in $GO_MODULES; do
		log "go mod download ($m)"
		( cd "$m" && go mod download )
	done
}

# ---------- Web deps ----------
step_npm_ci_web() {
	log "npm ci (web)"
	( cd web && npm ci )
}

# ---------- Website deps ----------
step_npm_ci_website() {
	log "npm ci (website)"
	( cd "$WEBSITE_DIR" && npm ci )
}

# ---------- uv (Python package installer for spec-kit) ----------
step_uv() {
	if command -v uv >/dev/null 2>&1; then
		return 0
	fi
	log "installing uv"
	curl -LsSf https://astral.sh/uv/install.sh | sh
}

# ---------- specify (spec-kit CLI for GitHub specs) ----------
step_specify() {
	if command -v specify >/dev/null 2>&1; then
		return 0
	fi
	log "installing specify (spec-kit) ${SPECIFY_VERSION}"
	uv tool install specify-cli --from "git+https://github.com/github/spec-kit.git@${SPECIFY_VERSION}"
}

# ---------- AI coding CLIs (optional) ----------
# Installed globally so every shell has `claude`, `opencode`, `gemini`, and
# `codex` on PATH. No credentials are baked in: each authenticates
# interactively at runtime (login or its API-key env var), keeping the image
# shareable and secret-free. Falls back to sudo if the node feature's global
# prefix isn't user-writable. Listed in OPTIONAL_STEPS, so a registry hiccup
# logs a WARN instead of failing the whole setup.
step_ai_clis() {
	local ai_clis=(@anthropic-ai/claude-code opencode-ai @google/gemini-cli @openai/codex)
	if ! command -v npm >/dev/null 2>&1; then
		log "skipping AI coding CLIs: this profile has no Node.js"
		return 0
	fi
	if command -v claude >/dev/null 2>&1 \
		&& command -v opencode >/dev/null 2>&1 \
		&& command -v gemini >/dev/null 2>&1 \
		&& command -v codex >/dev/null 2>&1; then
		return 0
	fi
	log "installing AI coding CLIs (claude, opencode, gemini, codex)"
	if npm install -g "${ai_clis[@]}"; then
		return 0
	fi
	if sudo npm install -g "${ai_clis[@]}"; then
		return 0
	fi
	echo "install failed; run 'npm install -g ${ai_clis[*]}' by hand" >&2
	return 1
}

# Runs one step. Steps run in a subshell with errexit so a failing command
# stops that step. errexit is turned off in the parent around the subshell,
# because bash ignores set -e inside a subshell that is part of an `if`
# condition.
run_step() {
	local step="$1" fn rc=0
	fn="step_${step}"
	if ! declare -F "$fn" >/dev/null; then
		die "unknown step in STEPS: $step"
	fi
	set +e
	( set -e; "$fn" )
	rc=$?
	set -e
	if [ "$rc" -ne 0 ]; then
		if is_optional "$step"; then
			log "WARN: ${step} failed (exit ${rc}); continuing"
		else
			die "step ${step} failed (exit ${rc})"
		fi
	fi
}

for step in $STEPS; do
	run_step "$step"
done

# ---------- Friendly summary: versions of installed tools only ----------
print_versions() {
	local tool
	log "tool versions"
	for tool in go node npm python3 docker kubectl helm kind oras golangci-lint uv specify; do
		command -v "$tool" >/dev/null 2>&1 || continue
		case "$tool" in
			go) go version ;;
			node) node --version ;;
			npm) npm --version ;;
			python3) python3 --version ;;
			docker) docker version --format 'docker {{.Server.Version}}' 2>/dev/null || echo "docker (server not running)" ;;
			kubectl) kubectl version --client=true --output=yaml 2>/dev/null | grep gitVersion || echo "kubectl (installed)" ;;
			helm) helm version --short ;;
			kind) kind version ;;
			oras) oras version | head -1 ;;
			golangci-lint) golangci-lint --version | head -1 ;;
			uv) uv --version ;;
			specify) specify --version ;;
		esac || true
	done
	for tool in claude opencode gemini codex; do
		command -v "$tool" >/dev/null 2>&1 || continue
		echo "$tool $("$tool" --version 2>/dev/null || echo '(installed; log in at runtime)')"
	done
}
print_versions || true

if [ -n "$READY" ] && [ -f "$READY" ]; then
	cat "$READY"
else
	log "ready. (no ready.txt at ${READY:-<unset>})"
fi
